const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const jobId = typeof $json.jobId === 'string' ? $json.jobId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) error = { code: 'INVALID_SESSION', message: 'The research check needs a valid conversation and request ID.' };
else if (!/^[A-Za-z0-9:_-]{1,160}$/.test(jobId)) error = { code: 'INVALID_JOB_ID', message: 'Use the exact job ID returned when domain research started.' };
const proposedInput = { sessionId, requestId, jobId };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Completion Input').first().json;
const statusCode = Number($json.statusCode ?? 0);
// n8n puts text responses on `data` and parsed JSON on `body`; accept either.
const body = $json.body ?? $json.data ?? {};
const job = body.job ?? {};
const memory = body.memory;

// Research now finishes inside start_domain_research, so a job is either saved
// or it never got that far. Nothing here may invent a result.
let response;
if (statusCode === 404) {
  response = { ok: false, jobId: input.jobId, error: { code: 'RESEARCH_JOB_NOT_FOUND', message: 'No research job with that ID belongs to this conversation. Check the ID, or start the research again.' } };
} else if (statusCode < 200 || statusCode >= 300) {
  response = { ok: false, jobId: input.jobId, error: { code: 'RESEARCH_STATUS_FAILED', message: String(body?.error?.message ?? 'The research job could not be read.') } };
} else if (job.jobId !== input.jobId) {
  response = { ok: false, jobId: input.jobId, error: { code: 'RESEARCH_STATUS_FAILED', message: 'The research job could not be matched to this conversation.' } };
} else if (['completed', 'partial'].includes(String(job.status)) && memory && memory.domain === job.domain) {
  response = { ok: true, jobId: job.jobId, domain: job.domain, status: String(job.status), saved: true, researchedAt: String(memory.researchedAt ?? ''), memory,
    message: job.status === 'partial'
      ? 'This research was saved as partial. Report its warnings and thin evidence rather than filling the gaps.'
      : 'This research was saved to local business memory.' };
} else if (String(job.status) === 'queued') {
  // Registered but never saved: start_domain_research failed after registering.
  response = { ok: false, jobId: job.jobId, domain: job.domain, status: 'queued', saved: false, error: { code: 'RESEARCH_NOT_SAVED', message: 'That research job was registered but no findings were ever saved, so the run did not finish. Start the research again.' } };
} else {
  response = { ok: false, jobId: input.jobId, status: String(job.status ?? 'unknown'), saved: false, error: { code: 'RESEARCH_NOT_SAVED', message: 'That research job has no saved findings. Nothing can be reported for it.' } };
}
return { json: { ...input, job, response } };

const input = $('Validate Completion Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'RESEARCH_STATUS_FAILED', message: 'The research job could not be checked.' } };
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'complete_domain_research', proposedInput: JSON.stringify(input.proposedInput ?? {}), result: JSON.stringify(response), error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '', response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The tool result could not be written to the local audit table.';
return { json: response };
